/**
 * Responses API Provider
 *
 * Adapter for OpenAI's Responses API format.
 * This is the unified interface for all providers.
 */

import type { Message } from '../types';
import type { APITool } from '../tools/types';
import type {
  Provider,
  ProviderConfig,
  ProviderResponse,
  ProviderToolCall,
  ResponsesAPIInputItem,
  ResponsesAPIContentPart,
} from './types';

/**
 * Create a Responses API provider
 */
export function createResponsesAPIProvider(): Provider {
  return {
    name: 'responses-api',

    async stream(
      messages: Message[],
      tools: APITool[],
      config: ProviderConfig
    ): Promise<ReadableStream<Uint8Array>> {
      const baseUrl = config.baseUrl || 'https://api.openai.com/v1';
      const input = normalizeMessages(messages);

      const body: Record<string, unknown> = {
        model: config.model,
        input,
        stream: true,
        temperature: config.temperature,
        max_output_tokens: config.maxTokens,
      };

      // Add tools if provided
      if (tools.length > 0) {
        body.tools = tools.map(t => ({
          type: 'function',
          name: t.name,
          description: t.description,
          parameters: t.parameters,
        }));
      }

      // Add reasoning effort if enabled
      if (config.enableReasoningEffort && config.reasoningEffort) {
        body.reasoning = {
          effort: config.reasoningEffort,
          summary: 'auto',
        };
      }

      const response = await fetch(`${baseUrl}/responses`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${config.apiKey}`,
          'OpenAI-Beta': 'responses=v1',
        },
        body: JSON.stringify(body),
      });

      if (!response.ok) {
        const errorBody = await response.text();
        throw new Error(`Responses API error: ${response.status} - ${errorBody}`);
      }

      if (!response.body) {
        throw new Error('No response body');
      }

      return response.body;
    },

    async complete(
      messages: Message[],
      tools: APITool[],
      config: ProviderConfig
    ): Promise<ProviderResponse> {
      const baseUrl = config.baseUrl || 'https://api.openai.com/v1';
      const input = normalizeMessages(messages);

      const body: Record<string, unknown> = {
        model: config.model,
        input,
        stream: false,
        temperature: config.temperature,
        max_output_tokens: config.maxTokens,
      };

      // Add tools if provided
      if (tools.length > 0) {
        body.tools = tools.map(t => ({
          type: 'function',
          name: t.name,
          description: t.description,
          parameters: t.parameters,
        }));
      }

      // Add reasoning effort if enabled
      if (config.enableReasoningEffort && config.reasoningEffort) {
        body.reasoning = {
          effort: config.reasoningEffort,
          summary: 'auto',
        };
      }

      const response = await fetch(`${baseUrl}/responses`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${config.apiKey}`,
          'OpenAI-Beta': 'responses=v1',
        },
        body: JSON.stringify(body),
      });

      if (!response.ok) {
        const errorBody = await response.text();
        throw new Error(`Responses API error: ${response.status} - ${errorBody}`);
      }

      const data = await response.json();
      return parseResponse(data);
    },
  };
}

/**
 * Normalize messages to Responses API input format
 */
function normalizeMessages(messages: Message[]): ResponsesAPIInputItem[] {
  const result: ResponsesAPIInputItem[] = [];

  for (const m of messages) {
    if (m.role === 'tool') {
      // Tool result -> function_call_output
      result.push({
        type: 'function_call_output',
        call_id: m.toolCallId || '',
        output: typeof m.content === 'string' ? m.content : JSON.stringify(m.content),
      });
    } else if (m.role === 'assistant' && m.toolCalls && m.toolCalls.length > 0) {
      // Assistant with tool calls
      if (m.content) {
        result.push({
          role: 'assistant',
          content: normalizeContent(m.content),
        });
      }
      // Add each function_call
      for (const tc of m.toolCalls) {
        result.push({
          type: 'function_call',
          call_id: tc.id,
          name: tc.function.name,
          arguments: tc.function.arguments,
        });
      }
    } else if (m.role === 'system') {
      // System messages become instructions (handled separately)
      // Skip for now - instructions are passed at top level
    } else {
      // Regular user/assistant message
      result.push({
        role: m.role as 'user' | 'assistant',
        content: normalizeContent(m.content),
      });
    }
  }

  return result;
}

/**
 * Normalize content to Responses API format
 */
function normalizeContent(
  content: string | Message['content']
): string | ResponsesAPIContentPart[] {
  if (typeof content === 'string') {
    return content;
  }

  if (Array.isArray(content)) {
    return content.map(part => {
      if (part.type === 'text') {
        return { type: 'input_text' as const, text: part.text };
      } else if (part.type === 'image') {
        return { type: 'input_image' as const, image_url: part.imageUrl };
      } else if (part.type === 'file') {
        return { type: 'input_file' as const, file_url: part.fileUrl };
      }
      return { type: 'input_text' as const, text: '' };
    });
  }

  return '';
}

/**
 * Parse a non-streaming response
 */
function parseResponse(data: any): ProviderResponse {
  let content = '';
  let reasoning = '';
  const toolCalls: ProviderToolCall[] = [];

  for (const item of data.output || []) {
    if (item.type === 'message' && item.role === 'assistant') {
      for (const part of item.content || []) {
        if (part.type === 'output_text') {
          content += part.text;
        }
      }
    } else if (item.type === 'function_call') {
      toolCalls.push({
        id: item.call_id,
        name: item.name,
        arguments: item.arguments,
      });
    } else if (item.type === 'reasoning') {
      for (const part of item.content || []) {
        if (part.type === 'text') {
          reasoning += part.text;
        }
      }
    }
  }

  const hasToolCalls = toolCalls.length > 0;

  return {
    content,
    reasoning: reasoning || undefined,
    toolCalls,
    usage: {
      inputTokens: data.usage?.input_tokens || 0,
      outputTokens: data.usage?.output_tokens || 0,
    },
    finishReason: hasToolCalls ? 'tool_calls' : 'stop',
  };
}

/**
 * Default provider instance
 */
export const responsesAPIProvider = createResponsesAPIProvider();
